                            <input type="number" class="form-control form-control-sm" placeholder="Min"
                                   @bind="minPrice" @bind:event="oninput" min="0" />
                        </div>
                        <div class="col-6">
                            <input type="number" class="form-control form-control-sm" placeholder="Max"
                                   @bind="maxPrice" @bind:event="oninput" min="0" />
                        </div>
                    </div>

                    <div class="form-check mb-3">
                        <input class="form-check-input" type="checkbox" id="inStockOnly"
                               @bind="inStockOnly" />
                        <label class="form-check-label" for="inStockOnly">In Stock Only</label>
                    </div>

                    <div class="d-grid gap-2">
                        <button class="btn btn-primary btn-sm" @onclick="ApplyFilters">Apply Filters</button>
                        <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFilters">Clear Filters</button>
                    </div>
                </div>
            </div>
        </aside>

        @* ── Main Content Area ── *@
        <main class="col-lg-9">
            @if (errorMessage is not null)
            {
                <div class="alert alert-danger" role="alert">
                    <strong>Error:</strong> @errorMessage
                </div>
            }
            else if (isLoading)
            {
                <div class="d-flex justify-content-center align-items-center py-5">
                    <div class="spinner-border text-primary me-2" role="status"></div>
                    <span>Loading products…</span>
                </div>
            }
            else if (result is not null)
            {
                @* Toolbar *@
                <div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2">
                    <div>
                        <label class="form-label mb-0 me-2 fw-semibold" for="sortSelect">Sort by:</label>
                        <select id="sortSelect" class="form-select form-select-sm d-inline-block w-auto"
                                @onchange="OnSortChanged">
                            @foreach (var opt in sortOptions)
                            {
                                <option value="@opt.Value" selected="@(sortBy == opt.Value)">@opt.Label</option>
                            }
                        </select>
                    </div>
                    <span class="text-muted">
                        @if (result.TotalCount > 0)
                        {
                            var first = (result.Page - 1) * result.PageSize + 1;
                            var last = Math.Min(result.Page * result.PageSize, result.TotalCount);
                            <text>Showing @first–@last of @result.TotalCount products</text>
                        }
                        else
                        {
                            <text>0 products</text>
                        }
                    </span>
                </div>

                @* Product Grid or Empty State *@
                @if (result.Items.Count == 0)
                {
                    <div class="text-center py-5 text-muted">
                        <h5>No products found</h5>
                        <p>Try adjusting your filters or search criteria.</p>
                    </div>
                }
                else
                {
                    <div class="row row-cols-1 row-cols-sm-2 row-cols-md-3 g-3 mb-4">
                        @foreach (var product in result.Items)
                        {
                            <div class="col">
                                <ProductCard Product="product"
                                             OnProductSelected="HandleProductSelected"
                                             OnAddToCart="HandleAddToCart" />
                            </div>
                        }
                    </div>

                    @* Pagination *@
                    @if (totalPages > 1)
                    {
                        <nav aria-label="Product pagination">
                            <ul class="pagination justify-content-center">
                                <li class="page-item @(currentPage == 1 ? "disabled" : "")">
                                    <button class="page-link" @onclick="() => GoToPage(currentPage - 1)"
                                            disabled="@(currentPage == 1)">
                                        Previous
                                    </button>
                                </li>
                                @foreach (var p in GetPageNumbers())
                                {
                                    <li class="page-item @(p == currentPage ? "active" : "")">
                                        <button class="page-link" @onclick="() => GoToPage(p)">@p</button>
                                    </li>
                                }
                                <li class="page-item @(currentPage == totalPages ? "disabled" : "")">
                                    <button class="page-link" @onclick="() => GoToPage(currentPage + 1)"
                                            disabled="@(currentPage == totalPages)">
                                        Next
                                    </button>
                                </li>
                            </ul>
                        </nav>
                    }
                }
            }
        </main>
    </div>
</div>

